-- HR 入站同步：外部人员编号与本地人员建立稳定映射，避免用姓名匹配。
BEGIN;

CREATE TABLE IF NOT EXISTS "人员外部映射" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "外部系统编号" bigint NOT NULL,
    "外部人员编号" varchar(150) NOT NULL,
    "人员编号" integer NOT NULL,
    "外部更新时间" timestamp without time zone,
    "最后同步时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "是否在职" boolean NOT NULL DEFAULT TRUE,
    "备注" varchar(500),
    CONSTRAINT "pk_人员外部映射" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_人员外部映射_系统" FOREIGN KEY ("外部系统编号") REFERENCES "外部系统"("编号"),
    CONSTRAINT "fk_人员外部映射_人员" FOREIGN KEY ("人员编号") REFERENCES "人员"("编号"),
    CONSTRAINT "uq_人员外部映射_外部人员" UNIQUE ("外部系统编号", "外部人员编号"),
    CONSTRAINT "uq_人员外部映射_本地人员" UNIQUE ("外部系统编号", "人员编号")
);

CREATE INDEX IF NOT EXISTS "ix_人员外部映射_人员" ON "人员外部映射" ("人员编号", "是否在职");

UPDATE "系统迁移版本"
   SET "版本" = 57,
       "脚本" = '001-057',
       "检查摘要" = '增加 HR 外部人员映射和幂等同步基础表'
 WHERE "编号" = 1;

COMMIT;
